// Helper to create 70 questions for each category with strict balanced option length
function saveCategoryFile(filename, questions) {
  if (questions.length !== 70) {
    throw new Error(`File ${filename} must have exactly 70 questions, got ${questions.length}`);
  }
  // Check length parity: max length difference among 4 options should not exceed 15 chars or 3x ratio
  questions.forEach((q, idx) => {
    const lens = q.options.map(o => o.length);
    const minL = Math.min(...lens);
    const maxL = Math.max(...lens);
    if (maxL - minL > 25 && maxL / Math.max(minL, 1) > 2.5) {
      console.warn(`Parity warning in ${filename} Q${idx+1}: options=[${q.options.join(' | ')}]`);
    }
  });
  fs.writeFileSync(path.join(SERVER_DIR, filename), JSON.stringify(questions, null, 2), 'utf8');
  console.log(`✅ ${filename} written: 70 questions with balanced options`);
}

